import torch, b200probe as bp, statistics as st
src = r'''
__device__ __forceinline__ unsigned long long gt(){unsigned long long t; asm volatile("mov.u64 %0, %%globaltimer;":"=l"(t)); return t;}
__device__ __forceinline__ unsigned lda(const unsigned* p){unsigned v; asm volatile("ld.acquire.gpu.global.u32 %0,[%1];":"=r"(v):"l"(p):"memory"); return v;}
__device__ __forceinline__ unsigned ldr(const unsigned* p){unsigned v; asm volatile("ld.relaxed.gpu.global.u32 %0,[%1];":"=r"(v):"l"(p):"memory"); return v;}
// flag test: mode 0 acquire poll, 1 relaxed poll + fence; nflags lines
extern "C" __global__ void flag(unsigned* flags, unsigned* arrive, unsigned long long* out, int mode, int nflags){
  unsigned long long* o = out + blockIdx.x*4;
  if (threadIdx.x==0){
    atomicAdd(arrive,1);
    if (blockIdx.x==0){
      while (atomicAdd(arrive,0) < gridDim.x) {}
      unsigned long long t0=gt(); long long c0=clock64(); unsigned long long t;
      do { t=gt(); } while (t - t0 < 4000);
      long long c1=clock64();
      unsigned long long tr=gt();
      for (int f=0; f<nflags; f++) asm volatile("red.release.gpu.global.add.u32 [%0], 1;"::"l"(flags+f*32):"memory");
      o[0]=tr; o[1]=c1-c0; o[2]=t-t0;
    } else {
      const unsigned* fl = flags + (blockIdx.x % nflags)*32;
      if (mode==0){ while(lda(fl)==0){} }
      else { while(ldr(fl)==0){} asm volatile("fence.acq_rel.gpu;":::"memory"); }
      o[0]=gt();
    }
  }
  __syncthreads();
}
// ping-pong between block 0 and block peer
extern "C" __global__ void pp(unsigned* a, unsigned* b, long long* out, int peer, int iters){
  if (threadIdx.x) return;
  unsigned smid; asm("mov.u32 %0, %%smid;":"=r"(smid));
  if (blockIdx.x==0){ out[2]=smid; long long c0=clock64();
    for(int i=1;i<=iters;i++){ asm volatile("st.release.gpu.global.u32 [%0], %1;"::"l"(a),"r"(i):"memory"); while(lda(b)<(unsigned)i){} }
    out[0]=clock64()-c0; }
  else if (blockIdx.x==peer){ out[3]=smid;
    for(int i=1;i<=iters;i++){ while(lda(a)<(unsigned)i){} asm volatile("st.release.gpu.global.u32 [%0], %1;"::"l"(b),"r"(i):"memory"); } }
}
// barriers: mode 0 flat (one counter, poll), mode 1 two-level (8 groups)
extern "C" __global__ void bar(unsigned* cnt, unsigned long long* out, int mode, int delay_ns){
  if (threadIdx.x==0){
    unsigned long long t0=gt();
    unsigned long long d = (blockIdx.x*2654435761u) % (unsigned)delay_ns;
    while (gt()-t0 < d) {}
    unsigned long long ta=gt();
    unsigned G=gridDim.x;
    if (mode==0){
      asm volatile("red.release.gpu.global.add.u32 [%0], 1;"::"l"(cnt):"memory");
      while(lda(cnt)<G){}
    } else {
      int g = blockIdx.x & 7; unsigned gs = (G - g + 7)/8;
      unsigned old; asm volatile("atom.acq_rel.gpu.global.add.u32 %0,[%1],1;":"=r"(old):"l"(cnt+32*(1+g)):"memory");
      if (old==gs-1){ unsigned o2; asm volatile("atom.acq_rel.gpu.global.add.u32 %0,[%1],1;":"=r"(o2):"l"(cnt):"memory");
        if (o2==7){ for(int f=0;f<8;f++) asm volatile("st.release.gpu.global.u32 [%0], 1;"::"l"(cnt+32*(9+f)):"memory"); } }
      while(lda(cnt+32*(9+g))==0){}
    }
    out[blockIdx.x*2]=ta; out[blockIdx.x*2+1]=gt();
  }
  __syncthreads();
}
